            cp_path = cp.get('path', '')
            test_path = os.path.join(cp_path, rm_sheet)
            if os.path.isfile(test_path):
                if cp.get('readonly', False):
                    err("Cannot remove from readonly cheatpath")
                    sys.exit(1)
                os.remove(test_path)
                sys.exit(0)
        err(f"Cheatsheet {rm_sheet} not found")
        sys.exit(2)

    if edit_sheet:
        target_path = None
        found_cp = None

        for cp in config.get('cheatpaths', []):
            cp_name = cp.get('name', '')
            cp_path = cp.get('path', '')
            if path_name and cp_name != path_name:
                continue
            test_path = os.path.join(cp_path, edit_sheet)
            if os.path.isfile(test_path):
                found_cp = cp
                target_path = test_path
                break

        if found_cp and found_cp.get('readonly', False):
            writable_cp = None
            for cp in config.get('cheatpaths', []):
                if not cp.get('readonly', False):
                    writable_cp = cp
                    break
            if writable_cp:
                new_target = os.path.join(writable_cp.get('path', ''), edit_sheet)
                os.makedirs(os.path.dirname(new_target), exist_ok=True)
                import shutil
                shutil.copy2(target_path, new_target)
                target_path = new_target
            else:
                err("No writable cheatpath found")
                sys.exit(1)

        if not target_path:
            writable_cp = None
            for cp in config.get('cheatpaths', []):
                if path_name and cp.get('name', '') != path_name:
                    continue
                if not cp.get('readonly', False):
                    writable_cp = cp
                    break
            if not writable_cp:
                err("No writable cheatpath found")
                sys.exit(1)
            target_path = os.path.join(writable_cp.get('path', ''), edit_sheet)
            os.makedirs(os.path.dirname(target_path), exist_ok=True)
            if not os.path.isfile(target_path):
                open(target_path, 'w').close()

        editor = os.environ.get('EDITOR', 'nano')
        os.system(f"{editor} {target_path}")
        sys.exit(0)

    if list_sheets:
        sheets = list_cheatsheets(config, match_tags, path_name)
        rows = [["title", "tags", "cheatpath"]]
        if brief:
            rows = [["title", "tags"]]
        for s in sheets:
            tags_str = ",".join(s['tags'])
            if brief:
                rows.append([s['title'], tags_str])
            else:
                rows.append([s['title'], tags_str, s['cheatpath']])
        if len(rows) > 1:
            print_table(rows)
        sys.exit(0)

    if search_phrase:
        sheets = list_cheatsheets(config, match_tags, path_name)
        if not regex:
            search_phrase = re.escape(search_phrase)
        try:
            reg = re.compile(search_phrase, re.IGNORECASE)
        except re.error:
            err("Invalid regex")
            sys.exit(1)

        for s in sheets:
            matches = []
            for line in s['text'].splitlines():
                if reg.search(line):
                    matches.append(line)
            if matches:
                print(f"{s['title']}:")
                for m in matches:
                    if colorize:
                        m = reg.sub(lambda x: f"\033[31m{x.group()}\033[0m", m)
                    print(f"  {m}")
        sys.exit(0)

    if cheatsheets:
        sheet_name = cheatsheets[0]
        sheets = list_cheatsheets(config, match_tags, path_name)

        # exact match first
        for s in sheets:
            if s['title'] == sheet_name:
                if colorize:
                    for line in s['text'].splitlines():
                        if line.strip().startswith('#'):
                            print(f"\033[32m{line}\033[0m")
                        else:
                            print(line)
                else:
                    print(s['text'].strip())
                sys.exit(0)

        # brief match if brief list? "-b apt" actually means list sheets matching apt
        if brief:
            rows = [["title", "tags"]]
            for s in sheets:
                if sheet_name in s['title']:
                    tags_str = ",".join(s['tags'])
                    rows.append([s['title'], tags_str])
            if len(rows) > 1:
                print_table(rows)
            sys.exit(0)

        err(f"Cheatsheet {sheet_name} not found")
        sys.exit(2)

if __name__ == "__main__":
